<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Reinvention & Experience Partner</title>
  <meta name="description" content="Leap Studio is a global creative agency helping enterprises reinvent experiences at global scale." />
  <style>
    :root {
      --bg: #0a0a0a;
      --surface: #121212;
      --surface-2: #171717;
      --text: #ffffff;
      --muted: #b5b5b5;
      --line: #2a2a2a;
      --accent: #3a86ff;
      --accent-warm: #ffb347;
      --radius: 18px;
      --max: 1240px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, "Neue Haas Grotesk Display Pro", "Segoe UI", Roboto, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container { width: min(92%, var(--max)); margin: 0 auto; }
    .section { padding: 96px 0; }
    .eyebrow { color: var(--accent); letter-spacing: .09em; text-transform: uppercase; font-size: .78rem; font-weight: 700; }
    .section-title { font-size: clamp(1.8rem, 3vw, 3.2rem); line-height: 1.1; margin: 14px 0 16px; }
    .section-lead { color: var(--muted); max-width: 760px; margin: 0 0 34px; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(10,10,10,.88);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--line);
    }
    .header-inner {
      height: 74px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }
    .brand { font-size: 1.2rem; font-weight: 800; letter-spacing: .02em; }

    .nav {
      display: flex;
      align-items: center;
      gap: 18px;
      flex-wrap: wrap;
    }
    .nav a { color: #e3e3e3; font-size: .94rem; }
    .nav a:hover, .nav a:focus-visible { color: var(--accent); }

    .header-actions { display: flex; align-items: center; gap: 12px; }

    .lang-wrap { position: relative; }
    .lang-btn {
      background: transparent;
      color: var(--text);
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: 10px 14px;
      cursor: pointer;
      min-height: 44px;
    }
    .lang-menu {
      position: absolute;
      right: 0;
      top: calc(100% + 8px);
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 12px;
      min-width: 180px;
      display: none;
      overflow: hidden;
    }
    .lang-menu button {
      width: 100%;
      border: 0;
      background: transparent;
      color: var(--text);
      text-align: left;
      padding: 10px 12px;
      cursor: pointer;
      min-height: 44px;
    }
    .lang-menu button:hover { background: #1f1f1f; }
    .lang-menu.open { display: block; }

    .menu-toggle {
      display: none;
      min-height: 44px;
      min-width: 44px;
      border: 1px solid var(--line);
      background: transparent;
      color: var(--text);
      border-radius: 10px;
      cursor: pointer;
    }

    .hero {
      padding: 78px 0 30px;
      border-bottom: 1px solid var(--line);
    }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.05fr .95fr;
      gap: 28px;
      align-items: stretch;
    }
    .hero h1 {
      margin: 0 0 18px;
      font-size: clamp(2.5rem, 6.6vw, 5rem);
      line-height: .95;
      letter-spacing: -.02em;
    }
    .hero p { color: var(--muted); max-width: 540px; margin: 0; }

    .hero-carousel {
      background: linear-gradient(180deg, #141414, #101010);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 22px;
      position: relative;
      overflow: hidden;
      min-height: 320px;
    }
    .hero-track {
      display: flex;
      transition: transform .6s cubic-bezier(.2,.7,.2,1);
      will-change: transform;
      touch-action: pan-y;
    }
    .hero-slide {
      min-width: 100%;
      padding-right: 4px;
    }
    .slide-type { color: var(--accent-warm); font-size: .75rem; text-transform: uppercase; letter-spacing: .08em; font-weight: 700; }
    .hero-slide h3 { font-size: 1.55rem; line-height: 1.2; margin: 8px 0; }
    .hero-slide p { color: var(--muted); margin: 0 0 14px; }
    .chip {
      display: inline-block;
      border: 1px solid #333;
      border-radius: 999px;
      padding: 7px 12px;
      font-size: .8rem;
      color: #ddd;
    }

    .carousel-controls {
      margin-top: 18px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
    }
    .dots { display: flex; gap: 8px; }
    .dot {
      width: 9px; height: 9px;
      border-radius: 50%;
      border: 0;
      cursor: pointer;
      background: #434343;
    }
    .dot.active { background: var(--accent); }
    .arrow-group { display: flex; gap: 8px; }
    .arrow {
      min-width: 44px;
      min-height: 44px;
      border: 1px solid var(--line);
      border-radius: 11px;
      background: transparent;
      color: var(--text);
      cursor: pointer;
    }

    .team-tabs {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-bottom: 20px;
    }
    .team-tab {
      border: 1px solid var(--line);
      border-radius: 999px;
      background: transparent;
      color: #e5e5e5;
      padding: 9px 14px;
      cursor: pointer;
      min-height: 44px;
    }
    .team-tab.active { background: #1a1a1a; border-color: var(--accent); color: #fff; }

    .team-carousel-wrap {
      position: relative;
      overflow: hidden;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: var(--surface);
    }
    .team-track {
      display: flex;
      transition: transform .5s ease;
      touch-action: pan-y;
    }
    .team-card {
      min-width: 100%;
      display: grid;
      grid-template-columns: 240px 1fr;
      gap: 20px;
      padding: 20px;
      align-items: center;
    }
    .team-card img {
      width: 100%;
      aspect-ratio: 4 / 5;
      object-fit: cover;
      border-radius: 14px;
      filter: saturate(.85) contrast(1.02);
    }
    .team-meta h4 { margin: 0 0 6px; font-size: 1.3rem; }
    .team-meta p { margin: 0 0 10px; color: var(--muted); }
    .team-meta blockquote {
      margin: 14px 0;
      padding-left: 14px;
      border-left: 2px solid var(--accent);
      color: #f0f0f0;
      font-size: 1.05rem;
    }
    .office-link { color: var(--accent-warm); font-weight: 600; }

    .work-scroller {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(280px, 28vw);
      gap: 16px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: 10px;
    }
    .project-card {
      scroll-snap-align: start;
      border: 1px solid var(--line);
      border-radius: 15px;
      overflow: hidden;
      background: var(--surface-2);
      min-height: 310px;
    }
    .project-card img { height: 190px; width: 100%; object-fit: cover; filter: grayscale(.2) brightness(.85); }
    .project-card .content { padding: 14px; }
    .project-card h4 { margin: 0 0 8px; font-size: 1.08rem; }
    .project-card p { margin: 0; color: var(--muted); font-size: .92rem; }

    .cta-banner {
      background: linear-gradient(110deg, #101827, #1f1406 60%, #0f0f0f);
      border: 1px solid #2b2b2b;
      border-radius: 20px;
      padding: 36px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 20px;
      align-items: center;
    }
    .cta-banner h3 { margin: 0 0 8px; font-size: clamp(1.45rem, 2.7vw, 2.4rem); }
    .btn {
      min-height: 44px;
      border-radius: 999px;
      border: 0;
      padding: 10px 18px;
      font-weight: 700;
      cursor: pointer;
      background: var(--accent);
      color: #fff;
    }

    .grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 16px; }
    .grid-4 { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 16px; }
    .card {
      border: 1px solid var(--line);
      background: var(--surface);
      border-radius: 14px;
      padding: 18px;
    }
    .card h4 { margin: 0 0 8px; }
    .card p { margin: 0; color: var(--muted); }

    .footer {
      border-top: 1px solid var(--line);
      padding: 36px 0 60px;
      color: #bdbdbd;
      font-size: .92rem;
    }

    .cookie-banner {
      position: fixed;
      left: 18px;
      right: 18px;
      bottom: 18px;
      background: rgba(18,18,18,.98);
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 14px;
      z-index: 120;
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      justify-content: space-between;
    }
    .cookie-banner p { margin: 0; color: #d5d5d5; max-width: 640px; }
    .cookie-actions { display: flex; gap: 8px; flex-wrap: wrap; }
    .btn-secondary {
      min-height: 44px;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: transparent;
      color: var(--text);
      padding: 10px 14px;
      cursor: pointer;
    }

    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .grid-4 { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .grid-3 { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }

    @media (max-width: 780px) {
      .header-inner { height: auto; padding: 12px 0; align-items: flex-start; }
      .menu-toggle { display: inline-flex; align-items: center; justify-content: center; }
      .nav {
        display: none;
        width: 100%;
        flex-direction: column;
        align-items: flex-start;
        padding: 8px 0;
      }
      .nav.open { display: flex; }
      .header-actions { margin-left: auto; }
      .team-card { grid-template-columns: 1fr; }
      .work-scroller { grid-auto-columns: 82%; }
      .cta-banner { grid-template-columns: 1fr; padding: 22px; }
      .grid-4, .grid-3 { grid-template-columns: 1fr; }
      .section { padding: 78px 0; }
      .hero { padding-top: 46px; }
    }
  </style>
</head>
