  <script>
    const heroTrack = document.getElementById('heroTrack');
    const heroSlides = Array.from(heroTrack.children);
    const heroDots = document.getElementById('heroDots');
    let heroIndex = 0;
    let heroTimer;

    function renderHeroDots() {
      heroDots.innerHTML = '';
      heroSlides.forEach((_, i) => {
        const dot = document.createElement('button');
        dot.className = 'dot' + (i === heroIndex ? ' active' : '');
        dot.setAttribute('aria-label', `Go to hero slide ${i + 1}`);
        dot.addEventListener('click', () => goHero(i));
        heroDots.appendChild(dot);
      });
    }
    function goHero(i) {
      heroIndex = (i + heroSlides.length) % heroSlides.length;
      heroTrack.style.transform = `translateX(-${heroIndex * 100}%)`;
      renderHeroDots();
    }
    function nextHero(step = 1) { goHero(heroIndex + step); }

    document.getElementById('heroPrev').addEventListener('click', () => nextHero(-1));
    document.getElementById('heroNext').addEventListener('click', () => nextHero(1));
    function startHeroAuto() {
      clearInterval(heroTimer);
      heroTimer = setInterval(() => nextHero(1), 5200);
    }
    startHeroAuto();
    renderHeroDots();

    let startX = 0;
    heroTrack.addEventListener('touchstart', (event) => { startX = event.changedTouches[0].clientX; }, { passive: true });
    heroTrack.addEventListener('touchend', (event) => {
      const delta = event.changedTouches[0].clientX - startX;
      if (Math.abs(delta) > 40) nextHero(delta < 0 ? 1 : -1);
    });

    const teamData = {
      'North America': [
        { name: 'Ava Martinez', title: 'Partner, Experience Strategy', office: 'New York', quote: 'We turn boardroom ambition into experiences customers actually feel.', img: 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=800&q=60' },
        { name: 'Jordan Lee', title: 'Executive Creative Director', office: 'San Francisco', quote: 'Creative clarity is the shortest path from complexity to momentum.', img: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=800&q=60' }
      ],
