  <div class="cookie-banner" id="cookieBanner" role="dialog" aria-label="Cookie consent banner">
    <p>We use cookies to personalize content, analyze traffic, and improve your experience across regions.</p>
    <div class="cookie-actions">
      <button class="btn-secondary" id="cookieDecline">Decline all</button>
      <button class="btn-secondary" id="cookieManage">Manage settings</button>
      <button class="btn" id="cookieAccept">Accept all</button>
    </div>
  </div>

  <script>
    const heroTrack = document.getElementById('heroTrack');
    const heroSlides = Array.from(heroTrack.children);
    const heroDots = document.getElementById('heroDots');
    let heroIndex = 0;
    let heroTimer;

    function renderHeroDots() {
      heroDots.innerHTML = '';
      heroSlides.forEach((_, i) => {
        const dot = document.createElement('button');
        dot.className = 'dot' + (i === heroIndex ? ' active' : '');
        dot.setAttribute('aria-label', `Go to hero slide ${i + 1}`);
        dot.addEventListener('click', () => goHero(i));
        heroDots.appendChild(dot);
      });
    }
    function goHero(i) {
      heroIndex = (i + heroSlides.length) % heroSlides.length;
      heroTrack.style.transform = `translateX(-${heroIndex * 100}%)`;
      renderHeroDots();
    }
    function nextHero(step = 1) { goHero(heroIndex + step); }

    document.getElementById('heroPrev').addEventListener('click', () => nextHero(-1));
    document.getElementById('heroNext').addEventListener('click', () => nextHero(1));
    function startHeroAuto() {
      clearInterval(heroTimer);
      heroTimer = setInterval(() => nextHero(1), 5200);
    }
    startHeroAuto();
    renderHeroDots();

    let startX = 0;
    heroTrack.addEventListener('touchstart', (event) => { startX = event.changedTouches[0].clientX; }, { passive: true });
    heroTrack.addEventListener('touchend', (event) => {
      const delta = event.changedTouches[0].clientX - startX;
      if (Math.abs(delta) > 40) nextHero(delta < 0 ? 1 : -1);
    });

    const teamData = {
      'North America': [
        { name: 'Ava Martinez', title: 'Partner, Experience Strategy', office: 'New York', quote: 'We turn boardroom ambition into experiences customers actually feel.', img: 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=800&q=60' },
        { name: 'Jordan Lee', title: 'Executive Creative Director', office: 'San Francisco', quote: 'Creative clarity is the shortest path from complexity to momentum.', img: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=800&q=60' }
      ],
      'Asia': [
        { name: 'Mei Tan', title: 'Director, Service Innovation', office: 'Singapore', quote: 'Local cultural fluency is what makes global scale believable.', img: 'https://images.unsplash.com/photo-1488426862026-3ee34a7d66df?auto=format&fit=crop&w=800&q=60' },
        { name: 'Arjun Rao', title: 'Head of AI Product Design', office: 'Singapore', quote: 'The future of enterprise products is adaptive, trusted, and radically human.', img: 'https://images.unsplash.com/photo-1542204625-de293a43b7b4?auto=format&fit=crop&w=800&q=60' }
      ],
      'Europe': [
        { name: 'Sophie Laurent', title: 'Managing Director, Design', office: 'London', quote: 'Great design systems don’t constrain creativity—they scale it.', img: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=800&q=60' },
        { name: 'Lukas Weber', title: 'Principal, Sustainable Futures', office: 'Munich', quote: 'Regeneration is now a strategic design variable, not a side initiative.', img: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=800&q=60' }
      ],
      'Oceania': [
        { name: 'Chloe Nguyen', title: 'Associate Partner, Transformation', office: 'Melbourne', quote: 'Progress happens when strategy, design, and delivery move as one team.', img: 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=800&q=60' },
        { name: 'Ethan Brooks', title: 'Design Operations Lead', office: 'Melbourne', quote: 'Operational excellence is the invisible engine behind iconic experiences.', img: 'https://images.unsplash.com/photo-1504593811423-6dd665756598?auto=format&fit=crop&w=800&q=60' }
      ]
    };

    const teamTrack = document.getElementById('teamTrack');
    const teamDots = document.getElementById('teamDots');
    const regionTabs = Array.from(document.querySelectorAll('.team-tab'));
    let activeRegion = 'North America';
    let teamIndex = 0;

    function renderTeamCards() {
      const members = teamData[activeRegion];
      teamTrack.innerHTML = members.map(member => `
        <article class="team-card" aria-label="${member.name} from ${member.office}">
          <img src="${member.img}" alt="Portrait of ${member.name}" />
          <div class="team-meta">
            <h4>${member.name}</h4>
            <p>${member.title}</p>
            <blockquote>“${member.quote}”</blockquote>
            <a class="office-link" href="#contact">${member.office} office ↗</a>
          </div>
        </article>
      `).join('');
      teamIndex = 0;
      updateTeamPosition();
      renderTeamDots();
    }

    function updateTeamPosition() {
      teamTrack.style.transform = `translateX(-${teamIndex * 100}%)`;
      Array.from(teamDots.children).forEach((dot, i) => dot.classList.toggle('active', i === teamIndex));
    }

    function renderTeamDots() {
      const members = teamData[activeRegion];
      teamDots.innerHTML = '';
      members.forEach((member, i) => {
        const dot = document.createElement('button');
        dot.className = 'dot' + (i === teamIndex ? ' active' : '');
        dot.setAttribute('aria-label', `View ${member.name}`);
        dot.addEventListener('click', () => {
          teamIndex = i;
          updateTeamPosition();
        });
        teamDots.appendChild(dot);
      });
    }

    regionTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        activeRegion = tab.dataset.region;
        regionTabs.forEach(item => {
          const selected = item === tab;
          item.classList.toggle('active', selected);
          item.setAttribute('aria-selected', String(selected));
        });
        renderTeamCards();
      });
    });

    document.getElementById('teamPrev').addEventListener('click', () => {
      const len = teamData[activeRegion].length;
      teamIndex = (teamIndex - 1 + len) % len;
      updateTeamPosition();
    });
    document.getElementById('teamNext').addEventListener('click', () => {
      const len = teamData[activeRegion].length;
      teamIndex = (teamIndex + 1) % len;
      updateTeamPosition();
    });

    teamTrack.addEventListener('touchstart', (event) => { startX = event.changedTouches[0].clientX; }, { passive: true });
    teamTrack.addEventListener('touchend', (event) => {
      const delta = event.changedTouches[0].clientX - startX;
      if (Math.abs(delta) > 40) {
        const len = teamData[activeRegion].length;
        teamIndex = delta < 0 ? (teamIndex + 1) % len : (teamIndex - 1 + len) % len;
        updateTeamPosition();
      }
    });

    renderTeamCards();

    const langBtn = document.getElementById('langBtn');
    const langMenu = document.getElementById('langMenu');
    langBtn.addEventListener('click', () => {
      const open = langMenu.classList.toggle('open');
      langBtn.setAttribute('aria-expanded', String(open));
    });
    langMenu.querySelectorAll('button').forEach(button => {
      button.addEventListener('click', () => {
        langBtn.textContent = button.dataset.lang + ' ▾';
        langMenu.classList.remove('open');
        langBtn.setAttribute('aria-expanded', 'false');
      });
    });

    document.addEventListener('click', (event) => {
      if (!event.target.closest('.lang-wrap')) {
        langMenu.classList.remove('open');
        langBtn.setAttribute('aria-expanded', 'false');
      }
    });

    const cookieBanner = document.getElementById('cookieBanner');
    function closeCookieBanner(action) {
      localStorage.setItem('leap-cookie-choice', action);
      cookieBanner.style.display = 'none';
    }
    if (localStorage.getItem('leap-cookie-choice')) cookieBanner.style.display = 'none';
    document.getElementById('cookieAccept').addEventListener('click', () => closeCookieBanner('accept'));
    document.getElementById('cookieDecline').addEventListener('click', () => closeCookieBanner('decline'));
    document.getElementById('cookieManage').addEventListener('click', () => closeCookieBanner('manage'));

    const menuToggle = document.getElementById('menuToggle');
    const nav = document.getElementById('primaryNav');
    menuToggle.addEventListener('click', () => {
      const open = nav.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(open));
    });
  </script>
</body>
